t.script:
// ══════════════════════════════════════════════════════════════════
// UAT-003 — Smart Saved Location Autocomplete
// ══════════════════════════════════════════════════════════════════

// ── Load Google Maps dynamically ──
(function loadGoogleMaps() {
    var gmaps = document.createElement('script');
    gmaps.src = 'https://maps.googleapis.com/maps/api/js?key=AIzaSyALGj3dz0EYDy89J0odZscREtWGAcYkj3U&libraries=places';
    gmaps.async = true;
    gmaps.defer = true;
    document.head.appendChild(gmaps);
})();

// ── Facility Name Autocomplete (UAT-003 req 1-6) ─────────────────────
var acTimer = null;
var acInput = document.getElementById('loc_name');
var acResults = document.getElementById('autocomplete_results');
var lastQuery = '';

if (acInput) {
    acInput.addEventListener('input', function() {
        var q = this.value.trim();
        if (q === lastQuery) return;
        lastQuery = q;
        clearTimeout(acTimer);
        if (q.length < 2) {
            acResults.style.display = 'none';
            return;
        }
        acTimer = setTimeout(function() {
            fetch('/my/saved-locations/autocomplete?q=' + encodeURIComponent(q))
                .then(function(r) { return r.json(); })
                .then(function(data) {
                    acResults.innerHTML = '';
                    if (!data.results || data.results.length === 0) {
                        acResults.style.display = 'none';
                        return;
                    }
                    data.results.forEach(function(item) {
                        var div = document.createElement('a');
                        div.className = 'list-group-item list-group-item-action';
                        div.style.cursor = 'pointer';

                        var badge = item.source === 'shared' ?
                            '<span class="badge bg-success float-end">Known Facility</span>' :
                            '<span class="badge bg-secondary float-end">Saved</span>';

                        var label = item.chain ?
                            (item.chain + (item.branch ? ' — ' + item.branch : (item.city ? ' — ' + item.city : ''))) :
                            item.name;

                        var sub = [];
                        if (item.business && item.business !== item.chain) sub.push(item.business);
                        if (item.store_number) sub.push('Store #' + item.store_number);
                        if (item.street) sub.push(item.street);
                        if (item.city) sub.push(item.city + ', ' + item.province);

                        div.innerHTML = '<strong>' + escapeHtml(label) + '</strong>' + badge +
                            '<br/><small class="text-muted">' + escapeHtml(sub.join(' · ')) + '</small>';

                        div.addEventListener('click', function() {
                            prefillFromSuggestion(item);
                            acResults.style.display = 'none';
                            lastQuery = label;
                        });
                        acResults.appendChild(div);
                    });
                    acResults.style.display = 'block';
                });
        }, 250);
    });

    // Hide results when clicking outside
    document.addEventListener('click', function(e) {
        if (e.target !== acInput && !acResults.contains(e.target)) {
            acResults.style.display = 'none';
        }
    });
}

// ── Helper: set province dropdown by code (ON) or name (Ontario) ──
function setProvinceByCode(code) {
    if (!code) return;
    var provEl = document.getElementById('state_id_field');
    if (!provEl) return;
    var upper = code.toUpperCase().trim();
    // Try data-code match first (most precise)
    for (var i = 0; i < provEl.options.length; i++) {
        if (provEl.options[i].getAttribute('data-code') === upper) {
            provEl.selectedIndex = i;
            return;
        }
    }
    // Fallback: match option text
    for (var i = 0; i < provEl.options.length; i++) {
        if (provEl.options[i].text.toUpperCase() === upper) {
            provEl.selectedIndex = i;
            return;
        }
    }
}

function prefillFromSuggestion(item) {
    document.getElementById('loc_name').value = item.chain ?
        (item.chain + (item.branch ? ' - ' + item.branch : (item.city ? ' - ' + item.city : ''))) :
        item.name;
    document.getElementById('street_address').value = item.street || '';
    document.getElementById('city_field').value = item.city || '';
    document.getElementById('postal_code_field').value = item.postal_code || '';
    document.getElementsByName('dock_info')[0].value = item.dock_info || '';
    document.getElementsByName('opening_hours')[0].value = item.opening_hours || '';
    document.getElementById('loc_place_id').value = item.place_id || '';
    document.getElementById('loc_lat').value = item.latitude || 0;

    // UAT-004: Override Location Type from master facility's stop_type
    // Master data precedence > URL ?type= query parameter
    if (item.location_type) {
        var typeSelect = document.querySelector('select[name="location_type"]');
        if (typeSelect) {
            typeSelect.value = item.location_type;
        }
    }
    document.getElementById('loc_lng').value = item.longitude || 0;
    // Link to shared master dispatch location (UAT-003 req 6)
    if (item.source === 'shared' && item.dispatch_location_id) {
        document.getElementById('dispatch_location_id').value = item.dispatch_location_id;
    }
    if (item.liftgate_required) {
        document.getElementsByName('liftgate_required')[0].checked = true;
    }
    if (item.appointment_required) {
        document.getElementsByName('appointment_required')[0].checked = true;
    }
    if (item.forklift_available) {
        document.getElementsByName('forklift_available')[0].checked = true;
    }
    document.getElementById('chain_name').value = item.chain || '';
    document.getElementById('business_name').value = item.business || '';
    document.getElementById('store_number').value = item.store_number || '';
    // Auto-default branch name if not manually set
    var branchEl = document.getElementById('branch_name');
    var branchManual = document.getElementById('branch_name_manual');
    if (branchEl && branchManual && branchManual.value !== '1') {
        branchEl.value = item.branch || '';
    }

    // Auto-select province from suggestion (works for both shared and own locations)
    setProvinceByCode(item.province);

    // If a shared dispatch location was selected, try to fetch Google
    // Place details from master data
    if (item.source === 'shared') {
        // Province already set above
    }
}

// ── Branch Name Auto-Default (UAT-003 req 9) ────────────────────────
var branchEl = document.getElementById('branch_name');
var chainEl = document.getElementById('chain_name');
var cityEl = document.getElementById('city_field');
var branchManualEl = document.getElementById('branch_name_manual');
var branchManuallySet = branchManualEl ? branchManualEl.value === '1' : false;

function autoDefaultBranchName() {
    if (!branchEl || branchManuallySet) return;
    if (!branchEl.value || branchEl.value.trim() === '') {
        var chain = (chainEl ? chainEl.value.trim() : '') || '';
        var city = (cityEl ? cityEl.value.trim() : '') || '';
        if (chain && city) {
            branchEl.value = chain + ' - ' + city;
        } else if (chain) {
            branchEl.value = chain;
        }
    }
}

// Mark branch as manually edited
if (branchEl) {
    branchEl.addEventListener('input', function() {
        // Only mark manual once the user actually types something in
        if (branchEl.value && !branchManuallySet) {
            branchManuallySet = true;
            if (branchManualEl) branchManualEl.value = '1';
        }
    });
}

// Auto-default on chain or city change (only if not manually set)
if (chainEl) {
    chainEl.addEventListener('change', function() {
        autoDefaultBranchName();
    });
    chainEl.addEventListener('blur', function() {
        autoDefaultBranchName();
    });
}
if (cityEl) {
    cityEl.addEventListener('change', function() {
        autoDefaultBranchName();
    });
    cityEl.addEventListener('blur', function() {
        autoDefaultBranchName();
    });
}

// ── Google Places Address Autocomplete (UAT-003 req 10) ──────────────
function initGooglePlacesAutocomplete() {
    var streetInput = document.getElementById('street_address');
    if (!streetInput || typeof google === 'undefined' || !google.maps || !google.maps.places) {
        // Retry if Google Maps not loaded yet
        setTimeout(initGooglePlacesAutocomplete, 500);
        return;
    }

    var autocomplete = new google.maps.places.Autocomplete(streetInput, {
        componentRestrictions: { country: 'ca' },
        types: ['address'],
    });

    autocomplete.addListener('place_changed', function() {
        var place = autocomplete.getPlace();
        if (!place || !place.address_components) return;

        // Only fill address from Google if not already pre-filled from
        // a known facility (lat/lng not already set)
        var existingLat = parseFloat(document.getElementById('loc_lat').value) || 0;
        if (existingLat !== 0) return; // Already populated from known facility

        var comp = {};
        place.address_components.forEach(function(c) {
            c.types.forEach(function(t) { comp[t] = c; });
        });

        document.getElementById('street_address').value = [
            comp.street_number ? comp.street_number.long_name : '',
            comp.route ? comp.route.long_name : '',
        ].join(' ').trim() || place.name || '';

        document.getElementById('city_field').value =
            (comp.locality || comp.administrative_area_level_3 ||
             comp.sublocality || comp.postal_town || {}).long_name || '';

        document.getElementById('postal_code_field').value =
            (comp.postal_code || {}).long_name || '';

        var provCode = (comp.administrative_area_level_1 || {}).short_name || '';
        setProvinceByCode(provCode);

        document.getElementById('unit_field').value =
            (comp.subpremise || {}).long_name || '';

        document.getElementById('loc_place_id').value = place.place_id || '';
        document.getElementById('loc_lat').value = place.geometry ? place.geometry.location.lat() : 0;
        document.getElementById('loc_lng').value = place.geometry ? place.geometry.location.lng() : 0;
        document.getElementById('loc_formatted_address').value = place.formatted_address || '';

        // Auto-default branch name from chain + city
        autoDefaultBranchName();

        // Auto-default location name from formatted address if empty
        var nameEl = document.getElementById('loc_name');
        if (nameEl && (!nameEl.value || nameEl.value.trim() === '')) {
            nameEl.value = place.name || place.formatted_address || '';
        }
    });
}

// Initialize Google Places after page load
if (document.readyState === 'complete') {
    initGooglePlacesAutocomplete();
} else {
    window.addEventListener('load', function() {
        initGooglePlacesAutocomplete();
    });
}

function escapeHtml(str) {
    var div = document.createElement('div');
    div.appendChild(document.createTextNode(str));
    return div.innerHTML;
}
